\[\mathbf{v} - \mathbf{a} = \begin{pmatrix} -2 + t \\ 2 - 3t \\ 1 + 2t \end{pmatrix} - \begin{pmatrix} 1 \\ -1 \\ 2 \end{pmatrix} = \begin{pmatrix} -3 + t \\ 3 - 3t \\ -1 + 2t \end{pmatrix}.\][asy]
